const TIPS = ["IND", "REQ", "MOC", "MOÇ R", "PLO", "PLOLG", "PLC", "PDL", "PRE", "PELOM", "EMD"];
const TIPN: Record<string, string> = { IND: "Indicação", REQ: "Requerimento", MOC: "Moção", "MOÇ R": "Moção (MOÇ R)", PLO: "Projeto de Lei Ordinária", PLOLG: "Projeto de Lei (PLOLG)", PLC: "Projeto de Lei Complementar", PDL: "Projeto de Decreto Legislativo", PRE: "Projeto de Resolução", PELOM: "Proposta de Emenda à Lei Orgânica", EMD: "Emenda" };
const ELT: Record<string, Eixo> = { c: "cti", e: "esporte", s: "saude", i: "estr", r: "rural", d: "educ", a: "social", g: "seg", m: "mocao", o: "outros" };
const PTS: Pt[] = [D0, D1, D2, D3, D4, D5, D6].join("\n").split(/[~\n]/).filter((s: string) => s.length > 8).map((s: string) => {
  const f = s.split("|");
  const d = f[3] ?? "010125";
  const id = Number(f[0]);
  const rc = RMAP[id];
  const e0: Eixo = ELT[rc ? rc[0] : (f[4] ?? "o")] ?? "outros";
  return { id, t: TIPS[Number(f[1])] ?? "IND", n: Number(f[2]), d: `${d.slice(0, 2)}/${d.slice(2, 4)}/${d.slice(4, 6)}`, y: "20" + d.slice(4, 6), e: e0, s: rc ? rc[1] : ESEC[e0], m: Number(f[5]), tr: f[6] === "1", x: f.slice(7).join("|"), ord: Number(d.slice(4, 6) + d.slice(2, 4) + d.slice(0, 2)) * 100000 + id };
}).sort((a: Pt, b: Pt) => b.ord - a.ord);
const PV: Record<string, Pt[]> = {};
VER.forEach((v: Ver, i: number) => { PV[v.slug] = PTS.filter((p: Pt) => ((p.m >> i) & 1) === 1); });
function nAut(m: number): number { let c = 0; let x = m; while (x > 0) { c += x & 1; x = x >> 1; } return c; }
function coautores(m: number, slug: string): string[] { return VER.filter((v: Ver, i: number) => ((m >> i) & 1) === 1 && v.slug !== slug).map((v: Ver) => v.parl); }

