function cnt(slug: string, e: Eixo): number { return (PV[slug] ?? []).filter((p: Pt) => p.e === e).length; }
function topE(slug: string): Eixo {
  let b: Eixo = "estr"; let m = -1;
  for (const e of ACT) { const c = cnt(slug, e); if (c > m) { m = c; b = e; } }
  return b;
}
function quemFed(partido: string, e: string, n: number): Fed[] {
  const lista = THF[e] ?? THF.estr;
  const c = FED.filter((f: Fed) => f.atual && (f.partido === partido || lista.includes(f.nome)));
  const rank = (f: Fed): number => (f.partido === partido ? 0 : 100) + (lista.includes(f.nome) ? lista.indexOf(f.nome) : 50);
  return c.sort((a: Fed, b: Fed) => rank(a) - rank(b)).slice(0, n);
}
function quemEst(partido: string, n: number): Est[] {
  const atuais = EST.filter((x: Est) => x.grupo !== 3);
  const mesmo = atuais.filter((x: Est) => x.partido === partido || (partido === "PSB" && x.nome === "Beto Dois a Um"));
  const resto = atuais.filter((x: Est) => !mesmo.includes(x)).sort((a: Est, b: Est) => b.vcv - a.vcv);
  return [...mesmo.sort((a: Est, b: Est) => b.vcv - a.vcv), ...resto].slice(0, n);
}
function falta(fim: string): { txt: string; lvl: number } {
  if (!fim) return { txt: "prazo não divulgado", lvl: -1 };
  const ms = new Date(fim).getTime() - Date.now();
  if (ms < 0) return { txt: "encerrado", lvl: 3 };
  const d = Math.floor(ms / 86400000);
  return { txt: d === 0 ? "termina hoje!" : `faltam ${d} dia${d > 1 ? "s" : ""}`, lvl: d <= 7 ? 2 : d <= 30 ? 1 : 0 };
}
function prazoDe(id: string): Prazo { return PRAZOS.find((p: Prazo) => p.id === id) ?? PRAZOS[1]; }
function hoje(): string { return new Date().toLocaleDateString("pt-BR", { day: "numeric", month: "long", year: "numeric" }); }

function oficio(v: Ver, tipo: string, c: Ctx, f: Fed | undefined, e: Est | undefined): string {
  const ver = v.sexo === "F" ? "Vereadora" : "Vereador";
  const doa = v.sexo === "F" ? "da" : "do";
  const contato = [v.tel.startsWith("(") ? v.tel : "", v.email.includes("@") ? v.email : ""].filter((s: string) => s).join(" · ") || `Câmara Municipal: ${CAMARA_TEL}`;
  let dest = ""; let orc = ""; let prazo = "";
  if (tipo === "est") {
    dest = `A Sua Excelência\n${e ? e.nome : "[nome do(a) deputado(a) estadual]"}\nDeputado(a) Estadual – Assembleia Legislativa de Mato Grosso\nTelefone: ${e ? e.tel : "(65) 3313-6900 (central da ALMT)"}`;
    orc = "emenda parlamentar ao Orçamento do Estado de Mato Grosso para 2027";
    prazo = "Segundo o Ato 023/2026 da ALMT (conforme notícias), as emendas estaduais podem ser apresentadas de 01 a 07/12/2026.";
  } else if (tipo === "min") {
    dest = `A Sua Excelência o(a) Senhor(a)\n[nome do(a) titular]\n${ORGAO[c.eixo]}`;
    orc = "inclusão de Campo Verde em programa ou ação de apoio técnico e financeiro do órgão";
    prazo = "Solicitamos informar se há programa aberto, edital ou prazo para cadastro de proposta no Transferegov.";
  } else {
    dest = `A Sua Excelência\n${f ? f.nome : "[nome do(a) parlamentar]"}\n${f ? f.cargo.split(" · ")[0] : "[cargo]"}\nE-mail: ${f ? f.email : "[e-mail do gabinete]"} · Telefone: ${f ? f.tel : "[telefone]"}`;
    orc = "emenda parlamentar ao Orçamento da União para 2027 (LOA 2027)";
    prazo = "As emendas individuais à LOA 2027 podem ser apresentadas até 23/11/2026, às 22h de Brasília (CMO, Comunicado 8/2026).";
  }
  return [
    "CÂMARA MUNICIPAL DE CAMPO VERDE – ESTADO DE MATO GROSSO",
    `Gabinete ${doa} ${ver} ${v.parl}`,
    "",
    `Ofício nº ____/2026 – GAB/${v.parl}`,
    `Campo Verde-MT, ${hoje()}.`,
    "",
    dest,
    "",
    `Assunto: Solicitação de ${tipo === "min" ? "apoio" : "emenda parlamentar"} – ${c.objeto}`,
    "",
    "Excelentíssimo(a) Senhor(a),",
    "",
    `Cumprimentando-o(a) cordialmente, eu, ${v.completo}, ${ver} do Município de Campo Verde-MT pelo ${v.partido}, venho solicitar ${orc}, destinada a: ${c.objeto}.`,
    "",
    c.ref ? `A demanda consta da ${c.ref}, apresentada na Câmara Municipal de Campo Verde.` : "",
    "",
    "Justificativa: [descreva em poucas linhas a necessidade, o local e quantas pessoas serão atendidas].",
    "",
    "Beneficiário: Prefeitura Municipal de Campo Verde – CNPJ 24.950.495/0001-88.",
    `Modalidade sugerida: ${c.modal}.`,
    "Valor pretendido: [R$ ____] (a confirmar pela Prefeitura na ficha técnica do projeto).",
    prazo,
    "",
    "Coloco-me à disposição para os esclarecimentos necessários e agradeço a atenção.",
    "",
    "Atenciosamente,",
    "",
    "",
    "______________________________",
    v.completo.toUpperCase(),
    `${ver} – ${v.partido}`,
    "Câmara Municipal de Campo Verde-MT",
    `Contato: ${contato}`,
  ].filter((s: string, i: number, a: string[]) => !(s === "" && a[i - 1] === "")).join("\n");
}

export default function App() {
  const t = useGrokTheme();
  const C = t.dataviz.categorical;
  const [aba, setAba] = useState<string>("mun");
  const [aberto, setAberto] = useState<string>("");
  const [abre, setAbre] = useState<Record<string, boolean>>({});
  const [filtro, setFiltro] = useState<Record<string, string>>({});
  const [lim, setLim] = useState<Record<string, number>>({});
  const [ofi, setOfi] = useState<Record<string, string>>({});
  const [extra, setExtra] = useState<Record<number, string>>({});
  const [msg, setMsg] = useState<string>("");
  const [anoEm, setAnoEm] = useState<number>(0);
  const tog = (k: string) => setAbre((o: Record<string, boolean>) => ({ ...o, [k]: !o[k] }));

  const wrap: CSSProperties = { minWidth: 0, overflowWrap: "anywhere", wordBreak: "break-word", boxSizing: "border-box" };
  const box = (cor: string): CSSProperties => ({ ...wrap, background: t.bg.elevated, borderRadius: 16, border: `1px solid ${t.border.subtle}`, borderTop: `6px solid ${cor}`, padding: 16 });
  const chip = (cor: string, ativo: boolean): CSSProperties => ({ padding: "9px 14px", borderRadius: 999, border: `2px solid ${cor}`, background: ativo ? cor : "transparent", color: ativo ? t.text.onColor : t.text.primary, fontWeight: 600, cursor: "pointer", fontSize: 14, fontFamily: t.font.family });
  const btn = (cor: string): CSSProperties => ({ padding: "8px 12px", borderRadius: 10, border: "none", background: cor, color: t.text.onColor, fontWeight: 700, cursor: "pointer", fontSize: 14, fontFamily: t.font.family, textDecoration: "none", display: "inline-block" });
  const h = (txt: string, cor: string): ReactNode => (<div style={{ fontSize: 19, fontWeight: 800, color: cor, margin: "22px 0 8px" }}>{txt}</div>);
  const small = (txt: string): ReactNode => (<div style={{ fontSize: 12, color: t.text.tertiary, marginTop: 6 }}>{txt}</div>);
  const link = (u: string, label?: string): ReactNode => (u.startsWith("http") ? <a href={u.split(" ")[0]} target="_blank" rel="noreferrer" style={{ color: t.text.accent }}>{label ?? u.replace("https://", "")}</a> : <span style={{ color: t.text.tertiary }}>{u}</span>);
  const grid: CSSProperties = { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(min(100%, max(260px, calc((100% - 56px) / 5))), 1fr))", gap: 14 };
  const urg = (lvl: number): { c: string; bg: string } => lvl === 2 ? { c: t.text.danger, bg: t.fill.dangerSubtle } : lvl === 1 ? { c: t.text.warning, bg: t.fill.warningSubtle } : lvl === 0 ? { c: t.text.success, bg: t.fill.successSubtle } : { c: t.text.tertiary, bg: t.bg.base };
  const badge = (id: string): ReactNode => {
    const p = prazoDe(id); const f = falta(p.fim); const u = urg(f.lvl);
    return <span style={{ display: "inline-block", padding: "3px 10px", borderRadius: 999, background: u.bg, color: u.c, fontWeight: 800, fontSize: 13 }}>{f.lvl === 2 ? "🔥 " : "⏰ "}{f.txt}</span>;
  };
  const lista2 = (itens: string[], num: boolean): ReactNode => (
    <div style={{ display: "grid", gap: 6, marginTop: 4 }}>
      {itens.map((s: string, i: number) => (<div key={i} style={{ fontSize: 14, display: "flex", gap: 8 }}><b style={{ flexShrink: 0 }}>{num ? `${i + 1}.` : "•"}</b><span style={wrap}>{s}</span></div>))}
    </div>
  );
  const checklist = (k: string, itens: string[]): ReactNode => (
    <div style={{ display: "grid", gap: 6, marginTop: 4 }}>
      {itens.map((s: string, i: number) => { const kk = `ck-${k}-${i}`; const ok = !!abre[kk]; return (
        <div key={kk} onClick={() => tog(kk)} style={{ fontSize: 14, display: "flex", gap: 8, cursor: "pointer", opacity: ok ? 0.6 : 1 }}><b style={{ flexShrink: 0 }}>{ok ? "✅" : "⬜"}</b><span style={{ ...wrap, textDecoration: ok ? "line-through" : "none" }}>{i + 1}. {s}</span></div>
      ); })}
      <div style={{ fontSize: 12, color: t.text.tertiary }}>Toque em cada passo para marcar como feito.</div>
    </div>
  );
  const sub = (txt: string): ReactNode => (<div style={{ fontWeight: 800, fontSize: 14, marginTop: 12 }}>{txt}</div>);

  const fedMini = (p: Fed, motivo: string, cor: string): ReactNode => (
    <div key={p.nome} style={{ ...wrap, borderLeft: `4px solid ${cor}`, padding: "6px 10px", marginTop: 6, background: t.bg.base, borderRadius: 8 }}>
      <div style={{ fontWeight: 800 }}>{p.nome} <span style={{ color: cor }}>· {p.partido}</span></div>
      <div style={{ fontSize: 13, color: t.text.secondary }}>{p.cargo}</div>
      {motivo && <div style={{ fontSize: 13 }}>⭐ {motivo}</div>}
      <div style={{ fontSize: 13 }}>💰 {p.cv}</div>
      <div style={{ fontSize: 13 }}>📞 {p.tel}</div>
      <div style={{ fontSize: 13 }}>✉️ {p.email.includes("@") ? <a href={`mailto:${p.email}`} style={{ color: t.text.accent }}>{p.email}</a> : p.email}</div>
      <div style={{ fontSize: 13 }}>🌐 {link(p.site, "perfil oficial")}</div>
    </div>
  );
  const estMini = (e: Est, cor: string): ReactNode => (
    <div key={e.nome} style={{ ...wrap, borderLeft: `4px solid ${cor}`, padding: "6px 10px", marginTop: 6, background: t.bg.base, borderRadius: 8 }}>
      <div style={{ fontWeight: 800 }}>{e.nome} <span style={{ color: cor }}>· {e.partido}</span></div>
      <div style={{ fontSize: 13, color: t.text.secondary }}>{e.sit}</div>
      <div style={{ fontSize: 13 }}>🗳️ {e.votos}</div>
      <div style={{ fontSize: 13 }}>📞 {e.tel}</div>
      <div style={{ fontSize: 13 }}>✉️ e-mail: não publicado pela ALMT</div>
      <div style={{ fontSize: 13 }}>🌐 {link(e.site, "perfil na ALMT")}</div>
    </div>
  );
  const motivoDe = (f: Fed, partido: string): string => f.partido === partido ? `é do seu partido (${partido})` : "";

  const exp = (k: string, cor: string, head: ReactNode, body: ReactNode, destaque: string): ReactNode => {
    const on = !!abre[k];
    return (
      <div key={k} style={{ ...box(cor), borderTop: `${destaque ? 10 : 6}px solid ${cor}` }}>
        <div onClick={() => tog(k)} style={{ cursor: "pointer" }}>
          {destaque && <div style={{ display: "inline-block", fontSize: 12, fontWeight: 800, padding: "2px 10px", borderRadius: 999, background: cor, color: t.text.onColor, marginBottom: 6 }}>{destaque}</div>}
          {head}
          <div style={{ marginTop: 10, fontWeight: 800, color: cor, fontSize: 14 }}>{on ? "▲ Fechar" : "▼ Toque para ver mais"}</div>
        </div>
        {on && <div style={{ marginTop: 10, paddingTop: 10, borderTop: `1px dashed ${t.border.default}` }}>{body}</div>}
      </div>
    );
  };

  const prazoBloco = (id: string): ReactNode => {
    const p = prazoDe(id);
    return (
      <div style={{ fontSize: 14 }}>
        {sub("⏰ Prazo")}
        <div>{p.titulo}: <b>{p.quando}</b> {badge(id)}</div>
        {p.obs && <div style={{ fontSize: 13, marginTop: 2 }}>{p.obs}</div>}
        {small(`Fonte: ${p.fonte} · ${VERIF}`)}
      </div>
    );
  };
  const ajuda = (k: string): ReactNode => {
    const s = SEC[k] ?? SEC.F;
    return (
      <div style={{ fontSize: 14 }}>
        {sub("🙋 Onde pedir na prefeitura")}
        <div><b>{s.nome}</b> · 📞 {s.tel} · ✉️ <a href={`mailto:${s.email.split(" ")[0]}`} style={{ color: t.text.accent }}>{s.email}</a></div>
        <div style={{ marginTop: 4 }}>👉 {link(PEDIDO, "Fazer o pedido aqui (Ouvidoria online → Solicitação) ↗")} · {link(CARTA, "Carta de Serviços ↗")}</div>
        {small(`Contato: ${s.fonte} · ${VERIF}. O cadastro no Transferegov/InvestSUS é feito pela própria prefeitura.`)}
      </div>
    );
  };

  const copiar = (txt: string) => {
    try {
      navigator.clipboard.writeText(txt).then(() => setMsg("✅ Ofício copiado! Cole no Word ou no e-mail.")).catch(() => setMsg("Não consegui copiar aqui. Selecione o texto e copie com o dedo ou o mouse."));
    } catch (err) { setMsg("Não consegui copiar aqui. Selecione o texto e copie com o dedo ou o mouse."); }
  };
  const oficioBox = (k: string, v: Ver, c: Ctx, padrao: string): ReactNode => {
    const tipo = ofi[k] ?? "";
    const feds = quemFed(v.partido, THF[c.eixo] ? c.eixo : "estr", 1);
    const ests = quemEst(v.partido, 1);
    const txt = tipo ? oficio(v, tipo, c, feds[0], ests[0]) : "";
    const nomeArq = `oficio-${v.slug}-${tipo}`;
    return (
      <div style={{ marginTop: 12, padding: 12, borderRadius: 12, background: t.fill.accentSubtle }}>
        <div style={{ fontWeight: 800, fontSize: 15 }}>📝 Modelo de ofício pronto</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 8 }}>
          {[["fed", "🇧🇷 Deputado federal / senador"], ["est", "🏛️ Deputado estadual (ALMT)"], ["min", "🏢 Ministério / secretaria"]].map((o: string[]) => (
            <button key={o[0]} onClick={() => setOfi((x: Record<string, string>) => ({ ...x, [k]: tipo === o[0] ? "" : o[0] }))} style={chip(C[2], tipo === o[0] || (!tipo && o[0] === padrao && false))}>{o[1]}{o[0] === padrao ? " ⭐" : ""}</button>
          ))}
        </div>
        {!tipo && <div style={{ fontSize: 13, marginTop: 6 }}>Toque num botão para gerar o ofício com seus dados oficiais do SAPL. ⭐ = o mais indicado aqui.</div>}
        {tipo && (
          <div>
            <div style={{ ...wrap, whiteSpace: "pre-wrap", fontFamily: "Georgia, serif", fontSize: 13, lineHeight: 1.5, background: t.bg.elevated, borderRadius: 10, padding: 12, marginTop: 8, userSelect: "text", border: `1px solid ${t.border.default}` }}>{txt}</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 8 }}>
              <button onClick={() => copiar(txt)} style={btn(C[0])}>📋 Copiar</button>
              <a href={"data:application/msword;charset=utf-8," + encodeURIComponent(`<html><head><meta charset="utf-8"></head><body><pre style="font-family:Times New Roman;font-size:12pt;white-space:pre-wrap">${txt.replace(/</g, "&lt;")}</pre></body></html>`)} download={`${nomeArq}.doc`} style={btn(C[1])}>⬇️ Baixar .doc</a>
              <a href={"data:text/plain;charset=utf-8," + encodeURIComponent(txt)} download={`${nomeArq}.txt`} style={btn(C[3])}>⬇️ Baixar .txt</a>
            </div>
            {msg && <div style={{ fontSize: 13, marginTop: 6 }}>{msg}</div>}
            <div style={{ fontSize: 12, color: t.text.tertiary, marginTop: 6 }}>Preencha o número do ofício, a justificativa e o valor. O valor fica em branco porque só a ficha técnica da Prefeitura pode dizer o custo. Destinatário e contatos: dados oficiais deste app ({VERIF}).</div>
          </div>
        )}
      </div>
    );
  };

  const carregar = (id: number) => {
    setExtra((o: Record<number, string>) => ({ ...o, [id]: "carregando" }));
    try {
      Promise.all([
        fetch(`${SAPL}/api/materia/materialegislativa/${id}/`).then((r: Response) => r.json()),
        fetch(`${SAPL}/api/materia/tramitacao/?materia=${id}&page_size=1`).then((r: Response) => r.json()),
      ]).then((res: unknown[]) => {
        const a = res[0] as { ementa?: string };
        const b = res[1] as { results?: { __str__?: string }[] };
        const lst = b.results ?? [];
        const tr = lst.length ? (lst[0].__str__ ?? "").split(" | ").slice(1).join(" – ") : "sem tramitação registrada no SAPL";
        setExtra((o: Record<number, string>) => ({ ...o, [id]: `${a.ementa ?? ""}§${tr}` }));
      }).catch(() => setExtra((o: Record<number, string>) => ({ ...o, [id]: "erro" })));
    } catch (err) { setExtra((o: Record<number, string>) => ({ ...o, [id]: "erro" })); }
  };

  const pautaCard = (p: Pt, v: Ver, cor: string): ReactNode => {
    const k = `${v.slug}-pt-${p.id}`;
    const na = nAut(p.m);
    const co = coautores(p.m, v.slug);
    const eix = THF[p.e] ? p.e : "estr";
    const feds = quemFed(v.partido, eix, 2);
    const est = p.e === "rural" || p.e === "estr" ? quemEst(v.partido, 1) : [];
    const pz = p.e === "rural" ? "almt" : "loa";
    const ref = `${TIPN[p.t] ?? p.t} nº ${p.n}/${p.y}, de ${p.d} (${SAPL}/materia/${p.id})`;
    const objeto = p.x.replace(/…$/, "").trim();
    const ex = extra[p.id] ?? "";
    const [ementa, tram] = ex.includes("§") ? ex.split("§") : ["", ""];
    return exp(k, cor,
      <div>
        <div style={{ fontSize: 13, color: t.text.secondary }}>{EEMO[p.e]} <b>{p.t} {p.n}/{p.y}</b> · {p.d} {na > 1 && <span style={{ marginLeft: 4, padding: "1px 8px", borderRadius: 999, background: t.fill.warningSubtle, fontWeight: 700 }}>👥 coletiva ({na} vereadores)</span>}</div>
        <div style={{ fontSize: 15, marginTop: 4 }}>{p.x}</div>
      </div>,
      <div style={{ fontSize: 14 }}>
        {sub("📜 Dados da pauta (SAPL)")}
        <div><b>{TIPN[p.t] ?? p.t} nº {p.n}/{p.y}</b> · apresentada em {p.d} · tema: {ENOME[p.e]}</div>
        <div>Situação no SAPL: <b>{p.tr ? "em tramitação" : "tramitação encerrada"}</b></div>
        {ementa ? <div style={{ marginTop: 6 }}><b>Ementa completa:</b> {ementa}<div><b>Última tramitação:</b> {tram}</div></div>
          : ex === "carregando" ? <div style={{ marginTop: 6 }}>⏳ Buscando no SAPL…</div>
          : ex === "erro" ? <div style={{ marginTop: 6 }}>Não consegui buscar no SAPL a partir daqui. Abra o link abaixo para ler a ementa completa e a tramitação.</div>
          : <div style={{ marginTop: 6 }}><span style={{ color: t.text.secondary }}>Acima está um resumo da ementa.</span> <button onClick={() => carregar(p.id)} style={btn(cor)}>🔎 Ver ementa completa e tramitação</button></div>}
        {co.length > 0 && <div style={{ marginTop: 6 }}>👥 Coautores: {co.join(", ")}</div>}
        <div style={{ marginTop: 6 }}>🔗 {link(`${SAPL}/materia/${p.id}`, "Abrir no SAPL ↗")}</div>
        {p.e === "mocao" ? <div style={{ marginTop: 10 }}>👏 Moção é homenagem: não precisa de recurso.</div> : (
          <div>
            {sub("💰 Onde buscar recurso para esta pauta")}
            <div>{FONTE_EIXO[p.e]}</div>
            {sub("👤 Quem procurar")}
            {feds.map((f: Fed) => fedMini(f, motivoDe(f, v.partido), cor))}
            {est.map((x: Est) => estMini(x, cor))}
            {prazoBloco(pz)}
            {sub("👣 Próximo passo")}
            <div>Procure a <b>{(SEC[p.s] ?? SEC.F).nome}</b> e peça a ficha técnica / projeto desta pauta (o quê, onde, quanto custa). Depois gere o ofício abaixo e mande para {feds[0] ? feds[0].nome : "o parlamentar"} {pz === "almt" ? "ou para o deputado estadual antes de 01/12" : "até 23/11, 21h de Cuiabá"}.</div>
            {ajuda(p.s)}
            {oficioBox(k, v, { objeto, ref, modal: MODAL[p.e], eixo: p.e }, pz === "almt" ? "est" : "fed")}
          </div>
        )}
        {small(`Fonte: SAPL da Câmara de Campo Verde · ${VERIF}. Tema classificado pelas palavras da ementa (aproximado).`)}
      </div>, "");
  };

  const opCard = (o: Op, v: Ver, top: Eixo, k: number, cor: string): ReactNode => {
    const p = prazoDe(o.prazo);
    const quem: ReactNode = o.quem === "est" ? quemEst(v.partido, 3).map((e: Est) => estMini(e, cor))
      : o.quem === "bancada" ? FED.filter((f: Fed) => f.nome === "Coronel Fernanda").map((f: Fed) => fedMini(f, "coordenadora da bancada de MT", cor))
      : o.quem === "none" ? <div style={{ fontSize: 14 }}>Não depende de um parlamentar específico.</div>
      : quemFed(v.partido, o.quem === "saude" ? "saude" : top, 3).map((f: Fed) => fedMini(f, motivoDe(f, v.partido), cor));
    const ruim = o.aplica.startsWith("NÃO") || o.aplica === "Restrito";
    const ky = `${v.slug}-op-${o.id}`;
    const eix: Eixo = o.id === "sus" ? "saude" : top;
    const hk = ESEC[eix];
    return exp(ky, ruim ? t.text.tertiary : cor,
      <div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>{badge(o.prazo)}<span style={{ fontSize: 12, fontWeight: 700, color: ruim ? t.text.danger : t.text.success }}>{ruim ? "⚠️ " : "✅ "}{o.aplica}</span></div>
        <div style={{ fontWeight: 800, fontSize: 17, marginTop: 8 }}>{o.emoji} {o.titulo}</div>
        <div style={{ fontSize: 14, marginTop: 4 }}>⏰ <b>{p.quando}</b></div>
      </div>,
      <div>
        {sub("🪜 Como acessar, passo a passo (marque o que já fez)")}{checklist(ky, o.passos)}
        {sub("👤 Quem procurar")}{quem}
        {prazoBloco(o.prazo)}
        {sub("💵 Valores")}<div style={{ fontSize: 14 }}>{o.valor}</div>
        {sub("📄 Documentos e onde entregar")}{lista2(o.docs, false)}
        <div style={{ fontSize: 14, marginTop: 4 }}>{o.links.map((l: [string, string]) => <span key={l[1]} style={{ marginRight: 12 }}>🔗 {link(l[1], l[0])}</span>)}</div>
        {ajuda(hk)}
        {sub("💡 Dica")}<div style={{ fontSize: 14 }}>{o.dica}</div>
        {!ruim && oficioBox(ky, v, { objeto: `[descreva o objeto] – ${ENOME[eix]}`, ref: "", modal: o.id === "pix" ? "emenda Pix (transferência especial), lembrando que o autor deve aplicar ao menos 70% das suas transferências especiais em despesas de capital" : o.id === "bancada" ? "emenda de bancada estadual (RP 7)" : MODAL[eix], eixo: eix }, o.quem === "est" ? "est" : "fed")}
        {small(`Fonte: ${o.fonte} · ${VERIF}`)}
      </div>,
      k < 2 && !ruim ? "⭐ Mais indicado para você" : "");
  };

  const eixoCard = (e: Eixo, v: Ver, top: Eixo, cor: string): ReactNode => {
    const info = EINFO[e]; const n = cnt(v.slug, e);
    const pt = (PV[v.slug] ?? []).find((p: Pt) => p.e === e);
    const feds = quemFed(v.partido, e, 3);
    const est = e === "rural" || e === "estr" ? quemEst(v.partido, 2) : [];
    const ky = `${v.slug}-ex-${e}`;
    const hk = ESEC[e];
    return exp(ky, cor,
      <div>
        <div style={{ fontSize: 30 }}>{info.emoji}</div>
        <div style={{ fontWeight: 800, fontSize: 17 }}>{info.nome}</div>
        <div style={{ fontSize: 13, color: t.text.secondary }}>{n} pautas suas neste tema (2025–26)</div>
        <div style={{ fontSize: 14, marginTop: 6 }}>{info.onde}</div>
      </div>,
      <div>
        {pt && <div style={{ fontSize: 14, padding: 8, borderRadius: 8, background: t.fill.accentSubtle }}>📜 Sua pauta mais recente neste tema: <b>{pt.t} {pt.n}/{pt.y}</b> – {pt.x} {link(`${SAPL}/materia/${pt.id}`, "(ver no SAPL)")}</div>}
        {sub("🪜 Como acessar (marque o que já fez)")}{checklist(ky, info.passos)}
        {sub("👤 Quem procurar (do seu partido primeiro, depois quem já mandou recurso)")}
        {feds.map((f: Fed) => fedMini(f, motivoDe(f, v.partido), cor))}
        {est.map((x: Est) => estMini(x, cor))}
        {prazoBloco(e === "rural" ? "almt" : "loa")}
        {sub("📄 Documentos e onde entregar")}{lista2(info.docs, false)}
        <div style={{ fontSize: 14, marginTop: 4 }}>{info.links.map((l: [string, string]) => <span key={l[1]} style={{ marginRight: 12 }}>🔗 {link(l[1], l[0])}</span>)}</div>
        {ajuda(hk)}
        {sub("💡 Dica")}<div style={{ fontSize: 14 }}>{info.dica}</div>
        {oficioBox(ky, v, { objeto: pt ? pt.x.replace(/…$/, "").trim() : `[descreva o objeto] – ${info.nome}`, ref: pt ? `${TIPN[pt.t] ?? pt.t} nº ${pt.n}/${pt.y}, de ${pt.d} (${SAPL}/materia/${pt.id})` : "", modal: MODAL[e], eixo: e }, e === "rural" ? "est" : "fed")}
        {small(`Fontes: Transferegov, CMO, SAPL · ${VERIF}`)}
      </div>,
      e === top ? "⭐ Sua bandeira principal" : "");
  };

  const pautas = (v: Ver, cor: string): ReactNode => {
    const k = `${v.slug}-pautas`; const on = !!abre[k];
    const todas = PV[v.slug] ?? [];
    const f = filtro[v.slug] ?? "";
    const colet = todas.filter((p: Pt) => nAut(p.m) > 1);
    const lista = f === "" ? todas.slice(0, 10) : f === "colet" ? colet : todas.filter((p: Pt) => p.e === f);
    const lk = `${v.slug}-${f}`; const mx = lim[lk] ?? 20;
    const mostra = f === "" ? lista : lista.slice(0, mx);
    const setF = (x: string) => { setFiltro((o: Record<string, string>) => ({ ...o, [v.slug]: f === x ? "" : x })); setAbre((o: Record<string, boolean>) => ({ ...o, [k]: true })); };
    const titulo = f === "" ? "As 10 mais recentes" : f === "colet" ? `Todas as ${lista.length} pautas coletivas` : `Todas as ${lista.length} pautas de ${EEMO[f as Eixo]} ${ENOME[f as Eixo]}`;
    return (
      <div style={{ ...box(cor), borderTop: `10px solid ${cor}`, marginTop: 18 }}>
        <button onClick={() => tog(k)} style={{ width: "100%", textAlign: "left", cursor: "pointer", background: cor, color: t.text.onColor, border: "none", borderRadius: 12, padding: "14px 16px", fontSize: 18, fontWeight: 800, fontFamily: t.font.family }}>
          📜 Pautas na Câmara – {todas.length} proposições em 2025–2026 {on ? "▲ fechar" : "▼ toque para abrir"}
        </button>
        <div style={{ fontSize: 13, marginTop: 8, color: t.text.secondary }}>👇 Toque num tema para ver TODAS as pautas dele. Toque de novo para voltar às 10 mais recentes.</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 }}>
          {TODOS_E.map((e: Eixo) => { const n = cnt(v.slug, e); const at = f === e; return (
            <button key={e} disabled={n === 0} onClick={() => setF(e)} style={{ ...chip(cor, at), fontSize: 13, padding: "5px 10px", opacity: n === 0 ? 0.4 : 1 }}>{EEMO[e]} {ENOME[e]}: <b>{n}</b></button>
          ); })}
          <button onClick={() => setF("colet")} style={{ ...chip(cor, f === "colet"), fontSize: 13, padding: "5px 10px" }}>👥 coletivas: <b>{colet.length}</b></button>
        </div>
        {on && (
          <div style={{ marginTop: 12 }}>
            <div style={{ fontWeight: 800, fontSize: 16, marginBottom: 6 }}>{titulo} {f !== "" && <button onClick={() => setF(f)} style={{ ...chip(cor, false), fontSize: 12, padding: "3px 10px", marginLeft: 6 }}>↩︎ voltar às 10</button>}</div>
            <div style={{ fontSize: 13, color: t.text.secondary, marginBottom: 8 }}>Cada pauta abre ao tocar: dados do SAPL, onde buscar recurso, quem procurar, prazo e ofício pronto.</div>
            <div style={grid}>{mostra.map((p: Pt) => pautaCard(p, v, cor))}</div>
            {f !== "" && lista.length > mx && <button onClick={() => setLim((o: Record<string, number>) => ({ ...o, [lk]: mx + 20 }))} style={{ ...btn(cor), marginTop: 10 }}>➕ Ver mais ({lista.length - mx} restantes)</button>}
            {small(`Fonte: SAPL da Câmara de Campo Verde (API pública) · ${VERIF}. ${todas.length} proposições de 2025–2026 (mandato atual). Tipos: IND = indicação, REQ = requerimento, MOC = moção, PLO/PLOLG/PLC = projetos de lei. Tema classificado pelas palavras da ementa (aproximado).`)}
          </div>
        )}
      </div>
    );
  };

  const emLinha = (x: EmR, cor: string): ReactNode => (
    <div key={x.cod} style={{ ...wrap, borderLeft: `4px solid ${cor}`, padding: "6px 10px", marginTop: 6, background: t.bg.base, borderRadius: 8, fontSize: 13 }}>
      <div style={{ fontWeight: 800, fontSize: 14 }}>{brl(x.valor)} · {x.parl}{x.partido !== "coletiva" ? ` (${x.partido})` : ""} · {x.ano}</div>
      <div>{x.tipo}: {x.objeto}</div>
      <div>📌 {x.status}</div>
      <div style={{ color: t.text.tertiary }}>{x.cod} · {link(x.href, "registro oficial no Transferegov ↗")}</div>
    </div>
  );
  const emendasBloco = (v: Ver): ReactNode => {
    const ver = v.sexo === "F" ? "esta vereadora" : "este vereador";
    const vinc = EMV[v.slug] ?? [];
    const emVinc = vinc.map((e: EmV) => ({ e, r: EMCV.find((x: EmR) => x.cod === e.cod) })).filter((o: { e: EmV; r: EmR | undefined }) => !!o.r);
    const totV = emVinc.reduce((s: number, o: { e: EmV; r: EmR | undefined }) => s + (o.r ? o.r.valor : 0), 0);
    const ped = PEDEM[v.slug] ?? [];
    const doPart = EMCV.filter((x: EmR) => x.partido === v.partido);
    const indiv = EMCV.filter((x: EmR) => x.indiv);
    const c1 = C[3 % C.length]; const c2 = C[4 % C.length]; const c3 = C[5 % C.length];
    const nota = <div style={{ ...wrap, fontSize: 13, padding: 8, borderRadius: 8, background: t.fill.warningSubtle, marginTop: 8 }}>⚖️ <b>Emendas são de autoria dos parlamentares; o vínculo com o vereador vem do documento oficial citado.</b></div>;
    return (
      <div>
        {h("💰 Emendas que ajudou a trazer", c1)}
        <div style={grid}>
          {exp(`${v.slug}-em-tot`, c1,
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: t.text.secondary }}>Com documento oficial</div>
              {emVinc.length > 0
                ? <div><div style={{ fontSize: 28, fontWeight: 900, color: c1 }}>{brl(totV)}</div><div style={{ fontSize: 14 }}>{emVinc.length} emenda(s) · {emVinc.length} documento(s) oficial(is)</div></div>
                : <div><div style={{ fontSize: 20, fontWeight: 900, color: c1, marginTop: 4 }}>0 emendas comprovadas</div><div style={{ fontSize: 14 }}>Nenhuma emenda com registro oficial vinculando a {ver}.</div></div>}
            </div>,
            <div style={{ fontSize: 14 }}>
              {nota}
              {emVinc.length > 0 && <div>{sub("📋 Emendas comprovadas")}{emVinc.map((o: { e: EmV; r: EmR | undefined }) => o.r ? <div key={o.e.cod}>{emLinha(o.r, c1)}<div style={{ fontSize: 13, marginLeft: 14 }}>📎 Vínculo: {link(o.e.docHref, o.e.doc)}</div></div> : null)}</div>}
              {sub("🔎 O que foi conferido (19/11/2026)")}
              {lista2(["SAPL da Câmara (2025–2026): nenhuma indicação, requerimento ou moção que cite um parlamentar e uma emenda específica já registrada.", "Notícias oficiais da Câmara de Campo Verde: nenhuma credita uma emenda de 2025–2026 a um dos 13 vereadores atuais.", "Transferegov (emendas Pix e saúde fundo a fundo 2025–2026 para Campo Verde): os registros trazem o parlamentar autor, não o vereador."], false)}
              {sub("🏅 Como registrar o seu crédito")}
              {checklist(`${v.slug}-em`, ["Protocole no SAPL uma indicação ou requerimento citando o parlamentar, o objeto e o valor. Use o botão Gerar ofício nas suas pautas.", "Mande o ofício ao gabinete e guarde o protocolo e a resposta.", "Quando a emenda aparecer no Transferegov, peça que o número dela conste em ata ou numa moção da Câmara citando o seu pedido.", "Peça ao gabinete do parlamentar que cite o seu nome na divulgação oficial da emenda."])}
              <div style={{ marginTop: 8 }}>👉 {link(SAPL, "SAPL da Câmara ↗")} · {link(TGOV, "Transferegov ↗")} · {link("https://portaldatransparencia.gov.br/emendas", "Portal da Transparência – emendas ↗")}</div>
            </div>, "Só dado oficial")}
          {ped.length > 0 && exp(`${v.slug}-em-ped`, c2,
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: t.text.secondary }}>Pedidos de emenda que você já protocolou</div>
              <div style={{ fontSize: 24, fontWeight: 900, color: c2 }}>{ped.length} pedido(s)</div>
              <div style={{ fontSize: 14 }}>Nenhuma emenda registrada ainda para esses objetos.</div>
            </div>,
            <div style={{ fontSize: 14 }}>
              {ped.map((p: PedEm) => (
                <div key={p.n} style={{ ...wrap, borderLeft: `4px solid ${c2}`, padding: "6px 10px", marginTop: 6, background: t.bg.base, borderRadius: 8, fontSize: 13 }}>
                  <div style={{ fontWeight: 800, fontSize: 14 }}>{p.n} · {p.d}</div>
                  <div>{p.o}</div>
                  {p.obs && <div style={{ color: t.text.secondary }}>{p.obs}</div>}
                  <div>{link(`${SAPL}/materia/${p.sapl}`, "no SAPL ↗")} · {link(p.news, "notícia da Câmara ↗")}</div>
                </div>
              ))}
              {sub("➡️ Próximo passo")}
              <div>Esses pedidos vão ao Governo do Estado, sem citar um deputado. Para virar emenda, mande o ofício a um deputado estadual (ALMT) entre 01 e 07/12 e cite o número da indicação. Não achamos emenda para esses objetos nos registros federais de 2025–2026.</div>
              <div style={{ marginTop: 6 }}>👉 {link("https://www.al.mt.gov.br/parlamento/deputados", "Deputados da ALMT ↗")}</div>
            </div>, "")}
          {exp(`${v.slug}-em-ctx`, c3,
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: t.text.secondary }}>Contexto · do seu partido ({v.partido}) · NÃO atribuído a você</div>
              {doPart.length > 0
                ? <div><div style={{ fontSize: 24, fontWeight: 900, color: c3 }}>{brl(somaEm(doPart))}</div><div style={{ fontSize: 14 }}>{doPart.length} emenda(s) federal(is) para Campo Verde em 2025–2026</div></div>
                : <div style={{ fontSize: 15, marginTop: 4 }}>Nenhum parlamentar federal do {v.partido} mandou emenda para Campo Verde em 2025–2026.</div>}
            </div>,
            <div style={{ fontSize: 14 }}>
              <div style={{ ...wrap, fontSize: 13, padding: 8, borderRadius: 8, background: t.fill.accentSubtle }}>ℹ️ Estes valores são dos parlamentares do seu partido. Não foram trazidos por você, salvo documento oficial que diga isso.</div>
              {doPart.map((x: EmR) => emLinha(x, c3))}
              {sub("🏙️ Campo Verde no total (2025–2026)")}
              <div>{brl(somaEm(indiv))} em {indiv.length} emendas federais individuais e mais {brl(somaEm(EMCV.filter((x: EmR) => !x.indiv)))} em emendas de bancada e de comissão.</div>
              {small("Fonte: Transferegov, dados abertos (módulos Especiais e Parcerias), conferido em 19/11/2026. Emendas estaduais (ALMT) ainda não foram conferidas na fonte oficial do Estado e não entram nesta conta.")}
            </div>, "")}
        </div>
      </div>
    );
  };

  const detalhe = (v: Ver, cor: string): ReactNode => {
    const top = topE(v.slug);
    const ord = ACT.filter((e: Eixo) => cnt(v.slug, e) > 0).sort((a: Eixo, b: Eixo) => cnt(v.slug, b) - cnt(v.slug, a)).slice(0, 5);
    const pt = (PV[v.slug] ?? []).find((p: Pt) => p.e === top);
    const fed = quemFed(v.partido, top, 3);
    const f1 = fed[0];
    const mapa = quemFed(v.partido, top, 5);
    const est = quemEst(v.partido, 3);
    const e1 = est[0];
    const temFed = FED.some((f: Fed) => f.atual && f.partido === v.partido);
    const temEst = EST.some((x: Est) => x.grupo !== 3 && (x.partido === v.partido || (v.partido === "PSB" && x.nome === "Beto Dois a Um")));
    const opsOrd = (OPORD[top] ?? OPORD.outro).map((id: string) => OPS.find((o: Op) => o.id === id)).filter((o: Op | undefined): o is Op => !!o);
    const pautaTxt = pt ? `${pt.t} ${pt.n}/${pt.y} – ${pt.x}` : `um projeto de ${ENOME[top]}`;
    const ctx: Ctx = { objeto: pt ? pt.x.replace(/…$/, "").trim() : `[descreva o objeto] – ${ENOME[top]}`, ref: pt ? `${TIPN[pt.t] ?? pt.t} nº ${pt.n}/${pt.y}, de ${pt.d} (${SAPL}/materia/${pt.id})` : "", modal: MODAL[top], eixo: top };
    const ver = v.sexo === "F" ? "Vereadora" : "Vereador";
    const zap = `https://wa.me/?text=${encodeURIComponent(`Buscador de Recursos – ${ver} ${v.parl}: meu tema principal é ${ENOME[top]}. Prazo das emendas federais para 2027: 23/11, 21h de Cuiabá. Veja: ${APPURL}`)}`;
    const hk = pt ? pt.s : ESEC[top];
    const sn = (SEC[hk] ?? SEC.F).nome;
    const passos = [
      { n: "1", quando: "Hoje", t: `Monte a ficha de ${ENOME[top]}`, d: `Procure a ${sn} e peça a ficha técnica / projeto (o quê, onde, quanto custa) da sua pauta: ${pautaTxt}.`, prazo: "loa",
        body: <div>{sub("🪜 Como fazer (marque o que já fez)")}{checklist(`${v.slug}-p1`, ["Diga qual pauta quer transformar em projeto.", "A secretaria da área calcula o valor e define o local.", "Para obra: confira se o terreno está regularizado e se há projeto básico.", "Com a ficha pronta, siga para o passo 2."])}{sub("📄 A ficha precisa ter")}{lista2(["O que vai ser feito", "Onde (endereço ou comunidade)", "Quanto custa (mínimo R$ 400 mil para obra, R$ 200 mil para outros itens)", "Quem será atendido"], false)}{ajuda(hk)}{sub("💡 Erro comum")}<div style={{ fontSize: 14 }}>Pedir emenda sem valor nem local. O gabinete precisa disso para registrar.</div></div> },
      { n: "2", quando: "Até 23/11, 21h", t: f1 ? `Peça a emenda a ${f1.nome}` : "Peça a emenda federal", d: f1 ? `${f1.nome} (${f1.partido}) · 📞 ${f1.tel} · ✉️ ${f1.email}` : "", prazo: "loa",
        body: <div>{sub("Por que esse nome")}<div style={{ fontSize: 14 }}>{f1 && f1.partido === v.partido ? `É do seu partido (${v.partido}) e está no mandato agora, então pode apresentar emendas para 2027.` : `Seu partido (${v.partido}) não tem deputado federal nem senador em exercício por MT. ${f1 ? f1.nome : ""} é quem mais se alinha ao tema ${ENOME[top]}.`}</div>
          {sub("👤 Contatos oficiais (gabinete)")}{fed.map((f: Fed) => fedMini(f, motivoDe(f, v.partido), cor))}
          {prazoBloco("loa")}{sub("🪜 Como pedir")}{checklist(`${v.slug}-p2`, ["Gere o ofício abaixo e anexe a ficha.", "Mande por e-mail ao gabinete.", "Ligue no mesmo dia e peça a confirmação.", "Peça o número da emenda depois de 23/11."])}{oficioBox(`${v.slug}-p2`, v, ctx, "fed")}{ajuda(hk)}</div> },
      { n: "3", quando: "01 a 07/12", t: e1 ? `Peça a emenda estadual a ${e1.nome}` : "Peça a emenda estadual", d: e1 ? `${e1.nome} (${e1.partido}) · 📞 ${e1.tel}` : "", prazo: "almt",
        body: <div>{sub("Por que esse nome")}<div style={{ fontSize: 14 }}>{temEst ? `É do seu partido${v.partido === "PSB" ? " (ex-PSB, hoje PODE)" : ""} e está no mandato agora.` : `Seu partido não tem deputado estadual em exercício. Sugestão: os mais votados em Campo Verde em 2026.`}</div>
          {sub("👤 Contatos")}{est.map((x: Est) => estMini(x, cor))}{prazoBloco("almt")}{oficioBox(`${v.slug}-p3`, v, ctx, "est")}
          {sub("Depois que o dinheiro vier")}<div style={{ fontSize: 14 }}>Acompanhe com a {sn} se o recurso entrou e se a obra começou. Emenda Pix aparece no {link(TGOV, "Transferegov")}, módulo Especiais.</div>{ajuda(hk)}</div> },
    ];
    return (
      <div style={{ gridColumn: "1 / -1", ...box(cor), borderTop: `10px solid ${cor}` }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 18, alignItems: "center" }}>
          <div style={{ width: 140, height: 140, borderRadius: "50%", overflow: "hidden", border: `5px solid ${cor}`, flexShrink: 0 }}>
            <Image src={FOTO[v.slug] ?? "asset:clenio-joaquim.jpg"} alt={`Foto oficial de ${v.parl}`} fit="cover" width={140} height={140} />
          </div>
          <div style={{ flex: 1, minWidth: 0, ...wrap }}>
            <div style={{ fontSize: 26, fontWeight: 800 }}>{v.parl}</div>
            <div style={{ color: t.text.secondary }}>{ver} {v.completo} · <b style={{ color: cor }}>{v.partido}</b> · {v.votos.toLocaleString("pt-BR")} votos na eleição de 2024 (TSE)</div>
            <div style={{ marginTop: 6, fontSize: 14 }}>📞 {v.tel} · ✉️ {v.email}</div>
            <div style={{ fontSize: 14 }}>🏛️ Câmara: {CAMARA_TEL} · {link(`${SAPL}/parlamentar/${v.perfil}`, "perfil no SAPL")}</div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <button onClick={() => setAberto("")} style={chip(cor, true)}>Fechar ✕</button>
            <a href={zap} target="_blank" rel="noreferrer" style={{ ...btn(C[2]), textAlign: "center" }}>💬 Compartilhar no WhatsApp</a>
            <button onClick={() => { try { window.print(); } catch (err) { setMsg("Impressão indisponível aqui."); } }} style={btn(C[4])}>🖨️ Imprimir</button>
          </div>
        </div>

        <div style={{ ...wrap, marginTop: 14, padding: 14, borderRadius: 12, background: t.fill.accentSubtle, fontSize: 16, lineHeight: 1.55 }}>
          👋 <b>Olá, {v.parl}!</b> Pelas suas pautas de 2025–2026 no SAPL, o tema em que você mais atua é <b>{EEMO[top]} {ENOME[top]}</b> ({cnt(v.slug, top)} pautas). {SEMFED[v.partido] ?? ""} {temFed ? "" : "Por isso, o caminho em Brasília é pelos parlamentares que mais se alinham ao seu tema."} <b>Prazo mais importante agora: {prazoDe("loa").quando}</b> {badge("loa")}
        </div>

        <div style={{ ...wrap, marginTop: 10, padding: 12, borderRadius: 12, border: `2px dashed ${cor}`, fontSize: 16, lineHeight: 1.6 }}>
          🔊 <b>Resumo em 4 frases</b><br />
          1. Seu tema forte é {ENOME[top]}.<br />
          2. Peça hoje a ficha técnica do projeto à {sn}.<br />
          3. Mande o ofício para {f1 ? f1.nome : "um parlamentar federal"} até 23 de novembro, às 21h.<br />
          4. Em dezembro, peça também a {e1 ? e1.nome : "um deputado estadual"}, de 1º a 7.
        </div>

        {pautas(v, cor)}

        {h("✅ Minhas 3 prioridades agora (feitas para você)", C[0])}
        <div style={grid}>
          {passos.map((s) => exp(`${v.slug}-passo-${s.n}`, C[0],
            <div style={{ display: "flex", gap: 12 }}>
              <div style={{ width: 40, height: 40, borderRadius: "50%", background: C[0], color: t.text.onColor, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 20, flexShrink: 0 }}>{s.n}</div>
              <div style={wrap}>
                <div style={{ fontSize: 13, fontWeight: 700, color: t.text.secondary }}>{s.quando} {badge(s.prazo)}</div>
                <b>{s.t}</b>
                <div style={{ fontSize: 14 }}>{s.d}</div>
              </div>
            </div>, s.body, ""))}
        </div>

        {emendasBloco(v)}

        {h("🗺️ Mapa do poder – quem mais pode te ajudar", C[6 % C.length])}
        <div style={{ fontSize: 14, marginBottom: 6 }}>Ordem: primeiro do seu partido, depois quem já mandou recurso para Campo Verde no seu tema ({ENOME[top]}). Todos estão no mandato e podem apresentar emendas para 2027.</div>
        <div style={grid}>{mapa.map((f: Fed, i: number) => (
          <div key={f.nome} style={{ ...box(C[(i + 3) % C.length]) }}>
            <div style={{ fontSize: 22, fontWeight: 900, color: C[(i + 3) % C.length] }}>#{i + 1}</div>
            {fedMini(f, motivoDe(f, v.partido), C[(i + 3) % C.length])}
          </div>
        ))}</div>

        {h("🧭 Onde buscar dinheiro para os seus temas", C[1])}
        <div style={grid}>{ord.map((e: Eixo, k: number) => eixoCard(e, v, top, C[(k + 1) % C.length]))}</div>

        {h("📅 Oportunidades (na ordem que mais serve para você)", C[2])}
        <div style={grid}>{opsOrd.map((o: Op, k: number) => opCard(o, v, top, k, C[(k + 2) % C.length]))}</div>

        {h("🇧🇷 Federal – do seu partido", C[3])}
        {temFed ? <div style={grid}>{FED.filter((f: Fed) => f.partido === v.partido).map((f: Fed) => <div key={f.nome} style={box(C[3])}>{fedMini(f, f.atual ? "em exercício" : "eleito – assume em 2027", C[3])}</div>)}</div>
          : <div style={{ fontSize: 15 }}>Seu partido não tem deputado federal nem senador em exercício por MT. {FED.some((f: Fed) => f.partido === v.partido) ? "Há eleitos que assumem em 2027." : ""} Use o Mapa do poder acima.</div>}

        {h("🏛️ Estadual – do seu partido", C[5 % C.length])}
        {temEst ? <div style={grid}>{EST.filter((x: Est) => x.partido === v.partido || (v.partido === "PSB" && x.nome === "Beto Dois a Um")).map((x: Est) => <div key={x.nome} style={box(C[5 % C.length])}>{estMini(x, C[5 % C.length])}</div>)}</div>
          : <div style={{ fontSize: 15 }}>Seu partido não tem deputado estadual eleito ou em exercício por MT. Caminho alternativo: os mais votados em Campo Verde (veja a prioridade 3).</div>}

        {h("🏙️ Municipal – quem ajuda", C[6 % C.length])}
        <div style={grid}>
          <div style={box(C[6 % C.length])}><b>Secretaria do seu tema</b><div style={{ fontSize: 14 }}>{sn}</div><div style={{ fontSize: 14 }}>📞 {(SEC[hk] ?? SEC.F).tel}</div><div style={{ fontSize: 14 }}>✉️ {(SEC[hk] ?? SEC.F).email}</div><div style={{ fontSize: 14 }}>👉 {link(PEDIDO, "Fazer o pedido aqui ↗")}</div></div>
          <div style={box(C[6 % C.length])}><b>Câmara Municipal</b><div style={{ fontSize: 14 }}>📞 {CAMARA_TEL}</div><div style={{ fontSize: 14 }}>🌐 {link(SAPL)}</div></div>
          <div style={box(C[6 % C.length])}><b>Ouvidoria da Prefeitura</b><div style={{ fontSize: 14 }}>Pedidos a qualquer secretaria · 📞 0800 647 2012 · ✉️ {PREF_MAIL}</div><div style={{ fontSize: 14 }}>🌐 {link(CARTA, "Carta de Serviços (contatos de cada secretaria)")}</div></div>
        </div>
      </div>
    );
  };

  const timeline = (): ReactNode => (
    <div style={{ ...grid, gridTemplateColumns: "repeat(auto-fill, minmax(min(100%, max(220px, calc((100% - 56px) / 5))), 1fr))" }}>
      {PRAZOS.map((p: Prazo) => {
        const f = falta(p.fim); const u = urg(f.lvl);
        return (
          <div key={p.id} style={{ ...wrap, background: u.bg, borderRadius: 14, padding: 12, border: `2px solid ${u.c}` }}>
            <div style={{ fontWeight: 900, color: u.c, fontSize: 16 }}>{f.lvl === 2 ? "🔥 " : f.lvl === -1 ? "❔ " : "📅 "}{f.txt}</div>
            <div style={{ fontWeight: 700, fontSize: 14, marginTop: 4 }}>{p.titulo}</div>
            <div style={{ fontSize: 13 }}>{p.quando}</div>
            {p.obs && <div style={{ fontSize: 12, marginTop: 4 }}>{p.obs}</div>}
            <div style={{ fontSize: 11, color: t.text.tertiary, marginTop: 4 }}>Fonte: {link(p.href, p.fonte)}</div>
          </div>
        );
      })}
    </div>
  );
  const instCard = (i: Inst, cor: string): ReactNode => (
    <div key={i.nome} style={box(cor)}>
      <div style={{ fontWeight: 700, fontSize: 17 }}>{i.nome}</div>
      <div style={{ color: t.text.secondary, fontSize: 14, margin: "4px 0 8px" }}>{i.tipo}</div>
      <div style={{ fontSize: 14 }}>🤝 {i.parceria}</div>
      <div style={{ fontSize: 14 }}>👤 Na prefeitura: {i.resp}</div>
      <div style={{ fontSize: 14 }}>🌐 {link(i.site)}{i.site.includes("não respondeu") ? " – não respondeu no teste de 18/11" : ""}</div>
    </div>
  );
  const abas = [
    { id: "mun", label: "🏙️ Municipal", cor: C[0] }, { id: "est", label: "🏛️ Estadual", cor: C[1] }, { id: "fed", label: "🇧🇷 Federal", cor: C[2] },
    { id: "inst", label: "🤝 Instituições", cor: C[3] }, { id: "glo", label: "📖 Glossário", cor: C[4] },
  ];
  const grupoEst = (g: number, titulo: string) => (
    <div>
      {h(titulo, C[1])}
      <div style={grid}>{EST.filter((x: Est) => x.grupo === g).map((x: Est) => <div key={x.nome} style={box(C[1])}>{estMini(x, C[1])}<div style={{ fontSize: 13, marginTop: 6 }}>💰 Emendas para Campo Verde 2023–26: {x.emendas}</div></div>)}</div>
    </div>
  );

  const todasEmendas = (): ReactNode => {
    const anos = Array.from(new Set(EMT.map((r: EmT) => r[3]))).sort((a: number, b: number) => b - a);
    const rows = EMT.filter((r: EmT) => anoEm === 0 || r[3] === anoEm);
    const per = anoEm === 0 ? "todos os anos" : `ano ${anoEm}`;
    const esf = [
      { id: "F", nome: "🇧🇷 Federal – deputados federais, senadores, bancada, comissões e relator", cor: C[2 % C.length], nota: "Fonte: CGU – Portal da Transparência (arquivo de 18/11/2026). Valor = o que a Prefeitura, o Fundo Municipal de Saúde e entidades sem fins lucrativos de Campo Verde receberam; nas propostas de saúde de 2026 ainda sem pagamento, o valor aprovado. Período: 2015–2026 (ano da emenda)." },
      { id: "E", nome: "🏛️ Estadual – deputados da ALMT", cor: C[1 % C.length], nota: "Fonte: CGE-MT – Portal da Transparência de Mato Grosso (SIGCON/FIPLAN), consultado em 19/11/2026. Só convênios com proponente ou objeto exclusivo de Campo Verde. O portal cobre 2019–2026; os registros de Campo Verde começam em 2022." },
    ];
    const tot = somaT(rows);
    const stat = (rot: string, val: string, sub2: string, cor: string): ReactNode => (
      <div key={rot} style={{ ...wrap, borderRadius: 14, padding: 14, background: t.bg.elevated, border: `2px solid ${cor}` }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: t.text.secondary }}>{rot}</div>
        <div style={{ fontSize: 26, fontWeight: 900, color: cor }}>{val}</div>
        <div style={{ fontSize: 13 }}>{sub2}</div>
      </div>
    );
    const linhaT = (r: EmT, i: number, cor: string): ReactNode => (
      <div key={`${r[8]}-${i}`} style={{ ...wrap, borderLeft: `4px solid ${cor}`, padding: "6px 10px", marginTop: 6, background: t.bg.base, borderRadius: 8, fontSize: 13 }}>
        <div style={{ fontWeight: 800, fontSize: 14 }}>{brl(r[6])} · {r[3]} · {r[4]}</div>
        <div>{r[5]}</div>
        <div>📌 {r[7]}</div>
        <div style={{ color: t.text.secondary }}>🏢 {r[9]}</div>
        <div style={{ color: t.text.tertiary }}>{r[8]} · {r[0] === "F" ? (r[10] ? link(PTD + r[10], "registro oficial na CGU ↗") : link("https://portaldatransparencia.gov.br/emendas", "Portal da Transparência ↗")) : link(CGEMT, "portal da CGE-MT ↗ (pesquise o nº do convênio)")}</div>
      </div>
    );
    return (
      <div>
        {h("💰 Todas as emendas destinadas a Campo Verde", C[3 % C.length])}
        <div style={{ fontSize: 15, marginBottom: 8 }}>Separadas por esfera e por parlamentar. Toque em um parlamentar para ver cada emenda: ano, objeto, tipo, valor, situação e o link do registro oficial.</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12 }}>
          <button onClick={() => setAnoEm(0)} style={chip(C[3 % C.length], anoEm === 0)}>Todos os anos</button>
          {anos.map((a: number) => <button key={a} onClick={() => setAnoEm(a)} style={chip(C[3 % C.length], anoEm === a)}>{a}</button>)}
        </div>
        <div style={grid}>
          {stat(`Total geral · ${per}`, brl(tot), `${rows.length} emendas · ${brl(pagoT(rows))} com pagamento registrado`, C[3 % C.length])}
          {esf.map((e: { id: string; nome: string; cor: string; nota: string }) => { const l = rows.filter((r: EmT) => r[0] === e.id); return stat(e.id === "F" ? "🇧🇷 Federal" : "🏛️ Estadual (ALMT)", brl(somaT(l)), `${l.length} emendas · ${new Set(l.map((r: EmT) => r[1])).size} autores · ${brl(pagoT(l))} pagos`, e.cor); })}
          {stat("🏙️ Municipal", "—", "Campo Verde não possui emendas impositivas de vereadores", C[0])}
        </div>
        {esf.map((e: { id: string; nome: string; cor: string; nota: string }) => {
          const l = rows.filter((r: EmT) => r[0] === e.id);
          const grupos: Record<string, EmT[]> = {};
          l.forEach((r: EmT) => { (grupos[r[1]] = grupos[r[1]] ?? []).push(r); });
          const nomes = Object.keys(grupos).sort((a: string, b: string) => somaT(grupos[b]) - somaT(grupos[a]));
          return (
            <div key={e.id}>
              <div style={{ fontSize: 18, fontWeight: 800, color: e.cor, margin: "20px 0 4px" }}>{e.nome} · {brl(somaT(l))}</div>
              <div style={{ fontSize: 12, color: t.text.tertiary, marginBottom: 8 }}>{e.nota}</div>
              {nomes.length === 0 ? <div style={{ fontSize: 14 }}>Nenhuma emenda registrada para Campo Verde em {per}.</div> :
                <div style={grid}>{nomes.map((n: string, k: number) => { const g = grupos[n]; const cor = C[(k + (e.id === "F" ? 2 : 5)) % C.length]; return exp(`emt-${e.id}-${n}`, cor,
                  <div>
                    <div style={{ fontSize: 22, fontWeight: 900, color: cor }}>#{k + 1}</div>
                    <div style={{ fontWeight: 800, fontSize: 17 }}>{n}</div>
                    {g[0][2] && <div style={{ fontSize: 13, color: t.text.secondary }}>{g[0][2]}</div>}
                    <div style={{ fontSize: 24, fontWeight: 900, color: cor, marginTop: 4 }}>{brl(somaT(g))}</div>
                    <div style={{ fontSize: 13 }}>{g.length} emenda(s) · {brl(pagoT(g))} pagos</div>
                  </div>,
                  <div>{g.map((r: EmT, i: number) => linhaT(r, i, cor))}</div>, ""); })}</div>}
            </div>
          );
        })}
        <div style={{ fontSize: 18, fontWeight: 800, color: C[0], margin: "20px 0 4px" }}>🏙️ Municipal</div>
        <div style={{ fontSize: 14 }}>Campo Verde não possui emendas impositivas de vereadores.</div>
        <div style={{ ...wrap, fontSize: 13, padding: 10, borderRadius: 10, background: t.fill.accentSubtle, marginTop: 12 }}>
          ℹ️ <b>Fora da soma:</b> R$ 5,52 mi pagos pela CGU a empresas e pessoas com sede em Campo Verde (fornecedores de compras feitas em outros lugares, como aviação agrícola em 2020) e projetos estaduais regionais que incluem Campo Verde junto com outras cidades: {EMT_REG.map((r: [string, string, number, string]) => `${r[0]} (${brl(r[2])}, ${r[1]})`).join("; ")}. Repasses estaduais fundo a fundo sem convênio (ex.: Fundo Estadual de Saúde) não aparecem por município no portal da CGE-MT e não entram aqui.
        </div>
      </div>
    );
  };

  return (
    <Page title="Buscador de Recursos – Vereadores de Campo Verde" width="full">
    <div style={{ fontFamily: t.font.family, color: t.text.primary, background: t.bg.base, padding: "16px clamp(8px, 1.5vw, 24px) 40px", minHeight: "100vh", overflowX: "hidden", boxSizing: "border-box", width: "100%" }}>
      <div style={{ ...wrap, borderRadius: 20, padding: "22px 20px", background: `linear-gradient(120deg, ${C[0]}, ${C[2]}, ${C[4]})`, color: t.text.onColor }}>
        <div style={{ fontSize: 30, fontWeight: 800 }}>🔎 Buscador de Recursos</div>
        <div style={{ fontSize: 19, fontWeight: 600 }}>Vereadores de Campo Verde – MT</div>
        <div style={{ fontSize: 15, marginTop: 8 }}>Toque no seu card. Tudo abre ao clicar: suas pautas, passo a passo, quem procurar (com telefone e e-mail oficiais), prazos e ofício pronto. Dados oficiais {VERIF}.</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 12 }}>
          {["👥 13 vereadores", `📜 ${PTS.length} proposições no SAPL (2025–26)`, "⚡ R$ 14,1 mi aceitos em Pix (2021–26)", "💤 R$ 11,9 mi pendentes nas Pix de 2021–25"].map((s: string) => (<span key={s} style={{ background: "rgba(255,255,255,0.22)", borderRadius: 999, padding: "6px 12px", fontWeight: 600, fontSize: 14 }}>{s}</span>))}
        </div>
      </div>

      {h("⏰ Prazos para pedir recursos (contagem ao vivo)", t.text.danger)}
      {timeline()}

      {todasEmendas()}

      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, margin: "18px 0" }}>
        {abas.map((a: { id: string; label: string; cor: string }) => (<button key={a.id} onClick={() => setAba(a.id)} style={chip(a.cor, aba === a.id)}>{a.label}</button>))}
      </div>

      {aba === "mun" && (
        <div style={{ ...grid, gridTemplateColumns: "repeat(auto-fill, minmax(min(100%, max(240px, calc((100% - 56px) / 5))), 1fr))" }}>
          {VER.map((v: Ver, k: number) => {
            const cor = C[k % C.length];
            if (aberto === v.slug) return <Fragmentless key={v.slug}>{detalhe(v, cor)}</Fragmentless>;
            const top = topE(v.slug);
            return (
              <div key={v.slug} onClick={() => setAberto(v.slug)} style={{ ...box(cor), cursor: "pointer", borderTop: `10px solid ${cor}`, textAlign: "center" }}>
                <div style={{ width: 120, height: 120, borderRadius: "50%", overflow: "hidden", border: `5px solid ${cor}`, margin: "0 auto" }}>
                  <Image src={FOTO[v.slug] ?? "asset:clenio-joaquim.jpg"} alt={`Foto oficial de ${v.parl}`} fit="cover" width={120} height={120} />
                </div>
                <div style={{ fontSize: 20, fontWeight: 800, marginTop: 10 }}>{v.parl}</div>
                <div style={{ display: "inline-block", marginTop: 6, padding: "3px 12px", borderRadius: 999, background: cor, color: t.text.onColor, fontWeight: 700, fontSize: 13 }}>{v.partido}</div>
                <div style={{ fontSize: 14, marginTop: 8, color: t.text.secondary }}>{EEMO[top]} Mais atua em: {ENOME[top]}</div>
                <div style={{ fontSize: 14, color: t.text.secondary }}>📜 {(PV[v.slug] ?? []).length} pautas na Câmara (2025–26)</div>
                <div style={{ marginTop: 10, fontWeight: 700, color: cor }}>👆 Toque para abrir</div>
              </div>
            );
          })}
        </div>
      )}

      {aba === "est" && (
        <div>
          <div style={{ fontSize: 15 }}>Só aparecem deputados estaduais <b>em exercício</b> ou <b>eleitos em 2026</b>. Suplentes foram retirados. Votos: TSE, eleição de 04/10/2026, município de Campo Verde. Contatos: a ALMT não publica telefone nem e-mail dos gabinetes, só os da Mesa Diretora.</div>
          {grupoEst(1, "✅ Em exercício e reeleitos (2027–2031)")}
          {grupoEst(2, "⏳ Em exercício até 31/01/2027 (podem apresentar emendas de 01 a 07/12)")}
          {grupoEst(3, "🆕 Eleitos em 2026 – assumem em 01/02/2027")}
          {h("🏢 Governo de MT e secretarias", C[1])}
          <div style={grid}>{SECS.map((i: Inst) => instCard(i, C[1]))}</div>
          {small(`Fontes: ALMT (perfis e Estrutura Organizacional), TSE · ${VERIF}`)}
        </div>
      )}

      {aba === "fed" && (
        <div>
          {h("🇧🇷 Em exercício – podem apresentar emendas para 2027 até 23/11", C[2])}
          <div style={grid}>{FED.filter((f: Fed) => f.atual).map((f: Fed) => <div key={f.nome} style={box(C[2])}>{fedMini(f, "", C[2])}<div style={{ fontSize: 13, marginTop: 4 }}>🗳️ {f.votos}</div></div>)}</div>
          {h("🆕 Eleitos em 2026 – assumem em 01/02/2027", C[2])}
          <div style={grid}>{FED.filter((f: Fed) => !f.atual).map((f: Fed) => <div key={f.nome} style={box(C[2])}>{fedMini(f, "", C[2])}<div style={{ fontSize: 13, marginTop: 4 }}>🗳️ {f.votos}</div></div>)}</div>
          {h("🏛️ Ministérios e sistemas", C[2])}
          <div style={grid}>{MIN.map((i: Inst) => instCard(i, C[2]))}</div>
          {small(`Fontes: Câmara dos Deputados e Senado (dados abertos), TSE, CMO, Transferegov · ${VERIF}`)}
        </div>
      )}

      {aba === "inst" && (
        <div>
          {h("🤝 Instituições parceiras", C[3])}
          <div style={{ fontSize: 15, marginBottom: 10 }}>Parceria nem sempre envolve dinheiro: pode trazer professores, cursos, equipamentos e ajuda para disputar editais.</div>
          <div style={grid}>{INST.map((i: Inst) => instCard(i, C[3]))}</div>
          {small("Telefones das instituições: não informados aqui (use o site oficial) · sites testados em 18/11/2026")}
        </div>
      )}

      {aba === "glo" && (
        <div>
          {h("📖 Palavras que você vai ouvir", C[4])}
          <div style={grid}>{GLOS.map((g: { t: string; d: string }, k: number) => (<div key={g.t} style={box(C[k % C.length])}><div style={{ fontWeight: 800, fontSize: 18 }}>{g.t}</div><div style={{ fontSize: 15, marginTop: 6 }}>{g.d}</div></div>))}</div>
        </div>
      )}

      <div style={{ ...wrap, marginTop: 32, padding: 16, borderRadius: 14, textAlign: "center", background: `linear-gradient(90deg, ${C[4]}, ${C[0]})`, color: t.text.onColor, fontWeight: 700, fontSize: 16 }}>
        💚 Desenvolvido por Rigoberto Ximenes Lopes
        <div style={{ fontWeight: 400, fontSize: 13, marginTop: 4 }}>Fontes oficiais: SAPL da Câmara de Campo Verde, TSE, Câmara dos Deputados, Senado, ALMT, CMO/Congresso e Transferegov ({VERIF}). “Não informado” = não publicado nas fontes oficiais.</div>
      </div>
    </div>
    </Page>
  );
}

function Fragmentless(props: { children?: ReactNode }) {
  return <>{props.children}</>;
}
